    // lookupType returns the base type with the given name.
    // If the base type has not been encountered yet, a new
    // type with the given name but no associated declaration
    // is added to the type map.
    namedType* rec::lookupType(reader* r, gocpp::string name)
    {
        if(name == ""_s || name == "_"_s)
        {
            // no type docs for anonymous types
            return nullptr;
        }
        if(auto [typ, found] = r->types[name]; found)
        {
            return typ;
        }
        // type not found - add one without declaration
        auto typ = gocpp::InitPtr<namedType>([=](auto& x) {
            x.name = name;
            x.embedded = gocpp::make(gocpp::Tag<embeddedSet>());
            x.funcs = gocpp::make(gocpp::Tag<methodSet>());
            x.methods = gocpp::make(gocpp::Tag<methodSet>());
        });
        r->types[name] = typ;
        return typ;
    }

